  doc_content: t,
}}];

// SPRINT 6 v2 - arma asunto/cuerpo de la alerta de fallo de persistencia.
// Se ejecuta SOLO por la rama false de 'IF - ¿Persistió en Supabase?'.
const safe = (fn) => { try { return fn(); } catch (e) { return undefined; } };
const j = (nm) => safe(() => $(nm).item.json);
const rowId = (o) => o && (o.id || (Array.isArray(o) && o[0] && o[0].id));
const estado = (o) => o === undefined ? 'no ejecutado'
  : rowId(o) ? 'OK'
  : 'FALLO' + (o && o.error ? ' - ' + JSON.stringify(o.error).slice(0, 300) : '');

const prep = j('Preparar Datos para PDF') || {};
const atn  = j('Insert Atención Cardiología');
const tut  = j('Upsert Tutor');
const mas  = j('Upsert Mascota');
const eco  = j('Insert Datos Ecocardiografía');
const doc  = j('Crear Google Doc') || {};
const drv  = j('Nombrar y mover PDF') || {};
const mail = j('Enviar informe al tutor');
const idMyvete = safe(() => $('Webhook').item.json.body.filiacion.tutor.id_myvete) || 's/d';

const pasos = [
  'Upsert Tutor:        ' + estado(tut),
  'Upsert Mascota:      ' + estado(mas),
  'Insert Atención:     ' + estado(atn) + '   <-- KEYSTONE',
  'Insert Datos Eco:    ' + (eco === undefined ? 'no aplica (sin eco en el payload)' : estado(eco)),
  'Crear Google Doc:    ' + (doc.documentId ? 'OK' : 'FALLO'),
  'Guardar PDF Drive:   ' + (drv.id ? 'OK (' + (drv.webViewLink || '') + ')' : 'FALLO o pendiente de FOLDER_ID'),
  'Mail al tutor:       ' + (mail === undefined ? 'no se envió (tutor sin email)' : (mail.id ? 'ENVIADO' : 'FALLO')),
];

const asunto = '[MYVETE][ALERTA] Persistencia Supabase FALLÓ - ' + (prep.paciente || 'paciente s/d') + ' - ' + (prep.fecha || '');
const cuerpo = [
  'La ingesta de una consulta NO se guardó correctamente en Supabase.',
  'El informe PDF se generó igual; hay que cargar la consulta a mano en la base.',
  '',
  'Paciente:  ' + (prep.paciente || '') + '  (' + (prep.especie || '') + ' / ' + (prep.raza || '') + ')',
  'Tutor:     ' + (prep.apellidoTutor || '') + ', ' + (prep.nombreTutor || ''),
  'ID MyVete: ' + idMyvete,
  'Fecha:     ' + (prep.fecha || ''),
  'PDF del informe: ' + (drv.webViewLink || '(no disponible / ver ejecución)'),
  '',
  'ESTADO POR PASO:',
  ...pasos,
  '',
  'Error crudo del insert de Atención:',
  JSON.stringify((atn && atn.error) || atn || null).slice(0, 900),
].join('\n');

return [{ json: { alerta_asunto: asunto, alerta_cuerpo: cuerpo } }];
